mapper.select:
select

from RM_THREE_COLOR tc


        tc.CO_ID=#{coId}


        tc.CO_VENUES_ID=#{coVenuesId}

select ve.VENUES_NAME as venuesName, (select dict.DICT_CN_DESC from RM_SYS_DICT dict where dict.DICT_TYPE_CD='5001' and dict.DICT_CD=tc.CO_COLOR) as coColorNm, (select dict.DICT_CN_DESC from RM_SYS_DICT dict where dict.DICT_TYPE_CD='5002' and dict.DICT_CD=tc.CO_TYPE) as coTypeNm, (select dict.DICT_CN_DESC from RM_SYS_DICT dict where dict.DICT_TYPE_CD='7001' and dict.DICT_CD=tc.CO_STATE) as coStateNm, DATE_FORMAT(tc.CO_OCCUR_TM,'%Y-%m-%d %H:%i:%s') as occurTm, case tc.CO_STATE when '01' then DATE_FORMAT(tc.CO_HANDLE_TM,'%Y-%m-%d %H:%i:%s') else null end as handleTm, tc.CO_ID as coId, tc.CO_CONTENT as coContent, tc.CO_PROGRESS as coProgress, tc.CO_REMARK as coRemark, tc.CO_COLOR as coColor, tc.CO_TYPE as coType, tc.CO_STATE as coState, ve.VENUES_ID as coVenuesId, tc.CO_OCCUR_TM as coOccurTm, case tc.CO_STATE when '01' then tc.CO_HANDLE_TM else null end as coHandleTm, tc.CO_ID as coId, tc.CO_SHOW as coShow from RM_THREE_COLOR tc left join RM_VENUES_INFO ve on ve.VENUES_ID=tc.CO_VENUES_ID
tc.CO_VALID='1'
and tc.CO_COLOR=#{vo.searchOne}
and tc.CO_TYPE=#{vo.searchTwo}
and tc.CO_VENUES_ID=#{vo.searchThree}
AND ve.TOWN = #{vo.town}
AND ve.AREA = #{vo.area}
and ve.VENUES_ID IN
#{value}
order by tc.CO_SHOW desc,tc.CO_MODIFY_TM desc,tc.CO_CREATE_TM desc limit #{vo.page},#{vo.size}

SELECT
    count(tc.CO_ID)
from RM_THREE_COLOR tc
left join RM_VENUES_INFO ve on ve.VENUES_ID=tc.CO_VENUES_ID

    tc.CO_VALID='1'

        and tc.CO_COLOR=#{vo.searchOne}


        and tc.CO_TYPE=#{vo.searchTwo}


        and tc.CO_VENUES_ID=#{vo.searchThree}


        AND  ve.TOWN = #{vo.town}


        AND  ve.AREA = #{vo.area}


        and ve.VENUES_ID IN

            #{value}

mapper.update:
update RM_VENUES_INFO ve
set ve.THREE_COLOR = #{coColor} ,
    ve.LAST_MODIFIER  = #{coModifier},
    ve.LAST_MODIFY_TIME  = #{coModifyTm}
where ve.VENUES_ID=#{coVenuesId}

mapper.select:
SELECT DATE_FORMAT(period.periodDate,'%Y-%m-%d') as date, IFNULL(color.venue,0) as venue, IFNULL(color.cases,0) as cases, IFNULL(color.complaint,0) as complaint, IFNULL(color.works,0) as works, IFNULL(color.safe,0) as safe, IFNULL(color.manage,0) as manage FROM( SELECT DATE_SUB(CURDATE(), interval PERIOD_NO day) AS periodDate FROM RM_SYS_PERIOD sp where sp.PERIOD_NO < #{vo.size} and PERIOD_TYPE='day' ) period LEFT JOIN( select DATE_FORMAT(tc.CO_OCCUR_TM,'%Y-%m-%d') coOccurTm, SUM(CASE WHEN tc.CO_TYPE = '500201' THEN 1 ELSE 0 END) AS venue, SUM(CASE WHEN tc.CO_TYPE = '500202' THEN 1 ELSE 0 END) AS cases, SUM(CASE WHEN tc.CO_TYPE = '500203' THEN 1 ELSE 0 END) AS complaint, SUM(CASE WHEN tc.CO_TYPE = '500204' THEN 1 ELSE 0 END) AS works, SUM(CASE WHEN tc.CO_TYPE = '500205' THEN 1 ELSE 0 END) AS safe, SUM(CASE WHEN tc.CO_TYPE = '500206' THEN 1 ELSE 0 END) AS manage from RM_THREE_COLOR tc left join rm_venues_info ve on ve.VENUES_ID=tc.CO_VENUES_ID where ve.VENUES_STATUS='01' and tc.CO_COLOR in ('500101','500102') and DATE_FORMAT(tc.CO_OCCUR_TM,'%Y-%m-%d') > DATE_SUB(CURDATE(), interval #{vo.size} day)
AND ve.TOWN = #{vo.town}
AND ve.AREA = #{vo.area}
and ve.VENUES_ID IN
#{item}
group by tc.CO_OCCUR_TM )color on period.periodDate= color.coOccurTm ORDER BY period.periodDate

SELECT (@rownum := @rownum + 1) AS date, IFNULL(zh.venue,0) as venue, IFNULL(zh.cases,0) as cases, IFNULL(zh.complaint,0) as complaint, IFNULL(zh.works,0) as works, IFNULL(zh.safe,0) as safe, IFNULL(zh.manage,0) as manage FROM( SELECT sp.PERIOD_NO AS periodNo FROM RM_SYS_PERIOD sp where sp.PERIOD_TYPE='week' AND sp.PERIOD_NO <= DATE_FORMAT(CURDATE(),'%u') AND sp.PERIOD_NO > DATE_FORMAT(CURDATE(),'%u') - #{vo.size} order by PERIOD_NO) period LEFT JOIN ( select DATE_FORMAT(tc.CO_OCCUR_TM,'%u') weeks, DATE_FORMAT(tc.CO_OCCUR_TM,'%Y%u') years, SUM(CASE WHEN tc.CO_TYPE = '500201' THEN 1 ELSE 0 END) AS venue, SUM(CASE WHEN tc.CO_TYPE = '500202' THEN 1 ELSE 0 END) AS cases, SUM(CASE WHEN tc.CO_TYPE = '500203' THEN 1 ELSE 0 END) AS complaint, SUM(CASE WHEN tc.CO_TYPE = '500204' THEN 1 ELSE 0 END) AS works, SUM(CASE WHEN tc.CO_TYPE = '500205' THEN 1 ELSE 0 END) AS safe, SUM(CASE WHEN tc.CO_TYPE = '500206' THEN 1 ELSE 0 END) AS manage from RM_THREE_COLOR tc left join rm_venues_info ve on ve.VENUES_ID=tc.CO_VENUES_ID where ve.VENUES_STATUS='01' and tc.CO_COLOR in ('500101','500102') and DATE_FORMAT(tc.CO_OCCUR_TM,'%Y-%m-%d') > DATE_SUB(CURDATE(), interval #{vo.size}*7 day)
AND ve.TOWN = #{vo.town}
AND ve.AREA = #{vo.area}
and ve.VENUES_ID IN
#{item}
GROUP BY weeks ORDER BY years ) zh on period.periodNo=zh.weeks join (SELECT @rownum := 0) AS rn order by period.periodNo

SELECT period.periodDate as date, IFNULL(color.venue,0) as venue, IFNULL(color.cases,0) as cases, IFNULL(color.complaint,0) as complaint, IFNULL(color.works,0) as works, IFNULL(color.safe,0) as safe, IFNULL(color.manage,0) as manage FROM ( SELECT DATE_FORMAT(DATE_SUB(CURDATE(), INTERVAL sp.PERIOD_NO MONTH),'%Y-%m') AS periodDate FROM RM_SYS_PERIOD sp where sp.PERIOD_NO < #{vo.size} and PERIOD_TYPE='day' ) period LEFT JOIN ( select DATE_FORMAT(tc.CO_OCCUR_TM,'%Y-%m') coOccurTm, SUM(CASE WHEN tc.CO_TYPE = '500201' THEN 1 ELSE 0 END) AS venue, SUM(CASE WHEN tc.CO_TYPE = '500202' THEN 1 ELSE 0 END) AS cases, SUM(CASE WHEN tc.CO_TYPE = '500203' THEN 1 ELSE 0 END) AS complaint, SUM(CASE WHEN tc.CO_TYPE = '500204' THEN 1 ELSE 0 END) AS works, SUM(CASE WHEN tc.CO_TYPE = '500205' THEN 1 ELSE 0 END) AS safe, SUM(CASE WHEN tc.CO_TYPE = '500206' THEN 1 ELSE 0 END) AS manage from RM_THREE_COLOR tc left join rm_venues_info ve on ve.VENUES_ID=tc.CO_VENUES_ID where ve.VENUES_STATUS='01' and tc.CO_COLOR in ('500101','500102') and DATE_FORMAT(tc.CO_OCCUR_TM,'%Y-%m') > DATE_FORMAT(DATE_SUB(CURDATE(), INTERVAL #{vo.size} MONTH),'%Y-%m')
AND ve.TOWN = #{vo.town}
AND ve.AREA = #{vo.area}
and ve.VENUES_ID IN
#{item}
group by coOccurTm ) color on period.periodDate= color.coOccurTm ORDER BY period.periodDate

select SUM(CASE WHEN tc.CO_TYPE = '500201' THEN 1 ELSE 0 END) AS venue, SUM(CASE WHEN tc.CO_TYPE = '500202' THEN 1 ELSE 0 END) AS cases, SUM(CASE WHEN tc.CO_TYPE = '500203' THEN 1 ELSE 0 END) AS complaint, SUM(CASE WHEN tc.CO_TYPE = '500204' THEN 1 ELSE 0 END) AS works, SUM(CASE WHEN tc.CO_TYPE = '500205' THEN 1 ELSE 0 END) AS safe, SUM(CASE WHEN tc.CO_TYPE = '500206' THEN 1 ELSE 0 END) AS manage from RM_THREE_COLOR tc left join rm_venues_info ve on ve.VENUES_ID=tc.CO_VENUES_ID where ve.VENUES_STATUS='01' and tc.CO_COLOR in ('500101','500102')
AND ve.TOWN = #{vo.town}
AND ve.AREA = #{vo.area}
and ve.VENUES_ID IN
#{item}
